class Classroom {

    /*
    This is a class representing a classroom, capable of adding and removing courses, checking availability at a given time, and detecting conflicts when scheduling new courses.
    */

    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        /*
        Initialize the classroom management system.
        :param id: Int64, the id of classroom
        */
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        /*
        Add course to this.courses list if the course wasn't in it.
        :param course: Course, information of the course, including 'start_time', 'end_time' and 'name'
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        */
        if !this.courses.contains(course) {
            this.courses.add(course)
        }
    }

    public func remove_course(course: Course): Unit {
        /*
        Remove course from this.courses list if the course was in it.
        :param course: Course, information of the course, including 'start_time', 'end_time' and 'name'
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        >>> classroom.remove_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        */
        if this.courses.contains(course) {
            this.courses.remove(course)
        }
    }

    public func is_free_at(check_time: String): Bool {
        /*
        change the time format as 'yyyy/MM/dd HH:mm' and check the time is free or not in the classroom.
        :param check_time: String, the time need to be checked
        :return: true if the check_time does not conflict with every course time, or false otherwise.
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        >>> classroom.is_free_at('2023/09/01 10:00')
        true
        >>> classroom.is_free_at('2023/09/01 09:00')
        false
        */
        let fmt = "yyyy/MM/dd HH:mm"
        let ct = DateTime.parse(check_time, fmt)
        for course in this.courses {
            let start = DateTime.parse(course.start_time, fmt)
            let end = DateTime.parse(course.end_time, fmt)
            if start <= ct && ct <= end {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        /*
        Before adding a new course, check if the new course time conflicts with any other course.
        :param new_course: Course, information of the course, including 'start_time', 'end_time' and 'name'
        :return: false if the new course time conflicts(including two courses have the same boundary time) with other courses, or true otherwise.
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        >>> classroom.check_course_conflict({'name': 'SE', 'start_time': '2023/09/01 09:40', 'end_time': '2023/09/01 10:40'})
        false
        */
        let fmt = "yyyy/MM/dd HH:mm"
        let new_start = DateTime.parse(new_course.start_time, fmt)
        let new_end = DateTime.parse(new_course.end_time, fmt)

        for course in this.courses {
            let start = DateTime.parse(course.start_time, fmt)
            let end = DateTime.parse(course.end_time, fmt)

            // Overlap if ranges intersect at any point, including boundaries.
            if !(new_end < start || new_start > end) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    /*
    This is a class as a class registration system, allowing to register students, register them for classes, retrieve students by major, get a list of all majors, and determine the most popular class within a specific major.
    */

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        /*
        Initialize the registration system with the attribute students and students_registration_class.
        students is a list of student dictionaries, each student dictionary has the key of name and major.
        students_registration_class is a dictionaries, key is the student name, value is a list of class names
        */
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        /*
        register a student to the system, add the student to the students list, if the student is already registered, return 0, else return 1
        */
        let name: String = student.get("name")
        var exists: Bool = false

        var i: Int64 = 0
        while (i < this.students.size()) {
            let s: HashMap<String, String> = this.students.get(i)
            if (s.get("name") == name) {
                exists = true
                break
            }
            i = i + 1
        }

        if (exists) {
            return 0
        } else {
            this.students.add(student)
            return 1
        }
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        /*
        register a class to the student.
        :param student_name: String
        :param class_name: String
        :return a list of class names that the student has registered
        >>> registration_system = ClassRegistrationSystem()
        >>> registration_system.register_class("John", "CS101")
        >>> registration_system.register_class("John", "CS102")
        ["CS101", "CS102"]
        */
        var classes: ArrayList<String>

        if (this.students_registration_classes.containsKey(student_name)) {
            classes = this.students_registration_classes.get(student_name)
            classes.add(class_name)
            // No need to put again if the list is mutable, but keep consistency
            this.students_registration_classes.put(student_name, classes)
        } else {
            classes = ArrayList<String>()
            classes.add(class_name)
            this.students_registration_classes.put(student_name, classes)
        }

        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        /*
        get all students in the major
        :param major: String
        :return a list of student name
        >>> registration_system = ClassRegistrationSystem()
        >>> student1 = HashMap<String, String>([("name", "John"), ("major", "Computer Science")])
        >>> registration_system.register_student(student1)
        >>> registration_system.get_students_by_major("Computer Science")
        ["John"]
        */
        var result: ArrayList<String> = ArrayList<String>()

        var i: Int64 = 0
        while (i < this.students.size()) {
            let s: HashMap<String, String> = this.students.get(i)
            if (s.get("major") == major) {
                result.add(s.get("name"))
            }
            i = i + 1
        }

        return result
    }

    public func get_all_major(): ArrayList<String> {
        /*
        get all majors in the system
        :return a list of majors
        >>> registration_system = ClassRegistrationSystem()
        >>> student1 = HashMap<String, String>([("name", "John"), ("major", "Computer Science")])
        >>> registration_system.students = ArrayList<HashMap<String, String>>()
        >>> registration_system.students.add(student1)
        >>> registration_system.get_all_major()
        ["Computer Science"]
        */
        var majors: ArrayList<String> = ArrayList<String>()

        var i: Int64 = 0
        while (i < this.students.size()) {
            let s: HashMap<String, String> = this.students.get(i)
            let m: String = s.get("major")
            if (!majors.contains(m)) {
                majors.add(m)
            }
            i = i + 1
        }

        return majors
    }

    public func get_most_popular_class_in_major(major: String): String {
        /*
        get the class with the highest enrollment in the major.
        :return a string of the most popular class in this major
        >>> registration_system = ClassRegistrationSystem()
        >>> registration_system.students = ArrayList<HashMap<String, String>>([HashMap<String, String>([("name", "John"), ("major", "Computer Science")]), HashMap<String, String>([("name", "Bob"), ("major", "Computer Science")]), HashMap<String, String>([("name", "Alice"), ("major", "Computer Science")])])
        >>> registration_system.students_registration_classes = HashMap<String, ArrayList<String>>([("John", ArrayList<String>(["Algorithms", "Data Structures"])), ("Bob", ArrayList<String>(["Operating Systems", "Data Structures", "Algorithms"]))])
        >>> registration_system.get_most_popular_class_in_major("Computer Science")
        "Data Structures"
        */
        var counts: HashMap<String, Int64> = HashMap<String, Int64>()

        var i: Int64 = 0
        while (i < this.students.size()) {
            let s: HashMap<String, String> = this.students.get(i)
            if (s.get("major") == major) {
                let name: String = s.get("name")
                if (this.students_registration_classes.containsKey(name)) {
                    let classes: ArrayList<String> = this.students_registration_classes.get(name)
                    var j: Int64 = 0
                    while (j < classes.size()) {
                        let cls: String = classes.get(j)
                        if (counts.containsKey(cls)) {
                            let current: Int64 = counts.get(cls)
                            counts.put(cls, current + 1)
                        } else {
                            counts.put(cls, 1)
                        }
                        j = j + 1
                    }
                }
            }
            i = i + 1
        }

        if (counts.size() == 0) {
            return ""
        }

        var max_count: Int64 = -1
        var most_popular: String = ""

        let keys: ArrayList<String> = counts.keys()
        var k: Int64 = 0
        while (k < keys.size()) {
            let key: String = keys.get(k)
            let c: Int64 = counts.get(key)
            if (c > max_count) {
                max_count = c
                most_popular = key
            }
            k = k + 1
        }

        return most_popular
    }
}

import std.collection.ArrayList

class CombinationCalculator {

    /*
    This is a class that provides methods to calculate the number of combinations for a specific count, calculate all possible combinations, and generate combinations with a specified number of elements.
    */

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        /*
        Initialize the calculator with a list of data.
        */
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        /*
        Calculate the factorial of a number.
        :param n: The number to calculate the factorial of,Int64.
        :return: The factorial of the number,Int64.
        */
        var result: Int64 = 1
        var i: Int64 = 1
        while (i <= n) {
            result = result * i
            i = i + 1
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        /*
        Calculate the number of combinations for a specific count.
        :param n: The total number of elements,Int64.
        :param m: The number of elements in each combination,Int64.
        :return: The number of combinations,Int64.
        >>> CombinationCalculator.count(4, 2)
        6
        */
        if (m == 0 || n == m) {
            return 1
        }
        if (m < 0 || m > n) {
            return 0
        }
        return CombinationCalculator.factorial(n) / (CombinationCalculator.factorial(n - m) * CombinationCalculator.factorial(m))
    }

    public static func count_all(n: Int64): Int64 {
        /*
        Calculate the number of all possible combinations.
        :param n: The total number of elements,Int64.
        :return: The number of all possible combinations,Int64,if the number of combinations is greater than 2^63-1,return Int64.Max.
        >>> CombinationCalculator.count_all(4)
        15
        */
        if (n < 0) {
            return 0
        }
        if (n >= 63) {
            return Int64.Max
        }
        var one: Int64 = 1
        return (one << n) - 1
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        /*
        Generate combinations with a specified number of elements.
        :param m: The number of elements in each combination,Int64.
        :return: A list of combinations,ArrayList<ArrayList<String>>.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> calc.select(2)
        [['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D']]

        */
        let result = ArrayList<ArrayList<String>>()
        var temp = ArrayList<String>()
        var i: Int64 = 0
        while (i < m) {
            temp.add("")
            i = i + 1
        }
        this._select(0, temp, 0, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        /*
        Generate all possible combinations of  selecting elements from the given data list,and it uses the select method.
        :return: A list of combinations,ArrayList<ArrayList<String>>.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> calc.select_all()
        [['A'], ['B'], ['C'], ['D'], ['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D'], ['A', 'B', 'C'], ['A', 'B', 'D'], ['A', 'C', 'D'], ['B', 'C', 'D'], ['A', 'B', 'C', 'D']]

        */
        let all = ArrayList<ArrayList<String>>()
        var i: Int64 = 1
        let n: Int64 = this.datas.size()
        while (i <= n) {
            let part = this.select(i)
            var j: Int64 = 0
            let partSize: Int64 = part.size()
            while (j < partSize) {
                all.add(part.get(j))
                j = j + 1
            }
            i = i + 1
        }
        return all
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        /*
        Generate combinations with a specified number of elements by recursion.
        :param dataIndex: The index of the data to be selected,Int64.
        :param resultList: The list of elements in the combination,ArrayList<String>.
        :param resultIndex: The index of the element in the combination,Int64.
        :param result: The list of combinations,ArrayList<ArrayList<String>>.
        :return: Unit.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> result = ArrayList<ArrayList<String>>()
        >>> calc._select(0, ArrayList<String>(Array<String>(2, repeat: "")), 0, result)
        >>> result
        [['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D']]

        */
        let resultLen: Int64 = resultList.size()
        let resultCount: Int64 = resultIndex + 1
        if (resultCount > resultLen) {
            let snapshot = ArrayList<String>()
            var k: Int64 = 0
            while (k < resultLen) {
                snapshot.add(resultList.get(k))
                k = k + 1
            }
            result.add(snapshot)
            return
        }

        let endExclusive: Int64 = this.datas.size() + resultCount - resultLen
        var i: Int64 = dataIndex
        while (i < endExclusive) {
            resultList.set(resultIndex, this.datas.get(i))
            this._select(i + 1, resultList, resultIndex + 1, result)
            i = i + 1
        }
    }
}

