import std.math.abs
import std.sort.sort

class DataStatistics {

    /*
    This is a class for performing data statistics, supporting to calculate the mean, median, and mode of a given data set.
    */

    public func mean(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the average value of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the mean value
        >>> ds = DataStatistics()
        >>> ds.mean(ArrayList<Int64>([1, 2, 3, 4, 5]))
        3.00
        */
        let n = data.size()
        var total: Int64 = 0
        var i: Int64 = 0
        while i < n {
            total += data.get(i)
            i += 1
        }
        let avg: Float64 = Float64(total) / Float64(n)
        return round(avg, 2)
    }

    public func median(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the median of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the median value
        >>> ds = DataStatistics()
        >>> ds.median(ArrayList<Int64>([2, 5, 1, 3, 4]))
        3.00
        */
        let n = data.size()
        let sortedData = ArrayList<Int64>()
        var i: Int64 = 0
        while i < n {
            sortedData.add(data.get(i))
            i += 1
        }
        sort(sortedData)

        if n % 2 == 0 {
            let mid = n / 2
            let a = Float64(sortedData.get(mid - 1))
            let b = Float64(sortedData.get(mid))
            return round((a + b) / 2.0, 2)
        } else {
            let mid = n / 2
            return round(Float64(sortedData.get(mid)), 2)
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        /*
        Calculate the mode of a set of data
        :param data:ArrayList<Int64>, data list
        :return:ArrayList<Int64>, the mode
        >>> ds = DataStatistics()
        >>> ds.mode(ArrayList<Int64>([2, 2, 3, 3, 4]))
        [2, 3]
        */
        let n = data.size()
        let result = ArrayList<Int64>()
        if n == 0 {
            return result
        }

        let sortedData = ArrayList<Int64>()
        var i: Int64 = 0
        while i < n {
            sortedData.add(data.get(i))
            i += 1
        }
        sort(sortedData)

        var currentVal = sortedData.get(0)
        var currentCount: Int64 = 1
        var maxCount: Int64 = 0

        i = 1
        while i < n {
            let v = sortedData.get(i)
            if v == currentVal {
                currentCount += 1
            } else {
                if currentCount > maxCount {
                    result.clear()
                    result.add(currentVal)
                    maxCount = currentCount
                } else if currentCount == maxCount {
                    result.add(currentVal)
                }
                currentVal = v
                currentCount = 1
            }
            i += 1
        }

        // finalize last run
        if currentCount > maxCount {
            result.clear()
            result.add(currentVal)
            maxCount = currentCount
        } else if currentCount == maxCount {
            result.add(currentVal)
        }

        // result is already in ascending order due to scanning sorted data
        return result
    }
}

