        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        let lower: String = this.alphabetLower()
        let upper: String = this.alphabetUpper()
        let twentySix: Int64 = 26

        var normalizedShift: Int64 = ((shift % twentySix) + twentySix) % twentySix

        var result: String = ""
        var i: Int64 = 0
        let n: Int64 = ciphertext.length()
        while i < n {
            let ch: String = ciphertext.substring(i, i + 1)
            let lowerIdx: Int64 = this.indexInAlphabet(lower, ch)
            if lowerIdx != -1 {
                var newIdx: Int64 = (lowerIdx - normalizedShift) % twentySix
                if newIdx < 0 { newIdx = newIdx + twentySix }
                result = result + lower.substring(newIdx, newIdx + 1)
            } else {
                let upperIdx: Int64 = this.indexInAlphabet(upper, ch)
                if upperIdx != -1 {
                    var newIdxU: Int64 = (upperIdx - normalizedShift) % twentySix
                    if newIdxU < 0 { newIdxU = newIdxU + twentySix }
                    result = result + upper.substring(newIdxU, newIdxU + 1)
                } else {
                    result = result + ch
                }
            }
            i = i + 1
        }
        return result
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        let lower: String = this.alphabetLower()
        let upper: String = this.alphabetUpper()
        let twentySix: Int64 = 26

        let keyLen: Int64 = this.key.length()
        if keyLen == 0 {
            return ciphertext
        }

        var decrypted: String = ""
        var keyIndex: Int64 = 0

        var i: Int64 = 0
        let n: Int64 = ciphertext.length()
        while i < n {
            let ch: String = ciphertext.substring(i, i + 1)
            var isUppercase: Bool = (this.indexInAlphabet(upper, ch) != -1)
            var isLowercase: Bool = (this.indexInAlphabet(lower, ch) != -1)

            if isUppercase || isLowercase {
                let ki: Int64 = keyIndex % keyLen
                let keyCh: String = this.key.substring(ki, ki + 1)
                let keyChLower: String = this.toLowerChar(keyCh)
                var shift: Int64 = this.indexInAlphabet(lower, keyChLower)
                if shift == -1 {
                    shift = 0
                }

                let chLower: String = this.toLowerChar(ch)
                let idx: Int64 = this.indexInAlphabet(lower, chLower)
                var newIdx: Int64 = (idx - shift) % twentySix
                if newIdx < 0 { newIdx = newIdx + twentySix }

                let newLowerChar: String = lower.substring(newIdx, newIdx + 1)
                if isUppercase {
                    decrypted = decrypted + this.toUpperChar(newLowerChar)
                } else {
                    decrypted = decrypted + newLowerChar
                }

                keyIndex = keyIndex + 1
            } else {
                decrypted = decrypted + ch
            }

            i = i + 1
        }

        return decrypted
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        let n: Int64 = encrypted_text.length()
        if rails <= 1 || n <= 1 {
            return encrypted_text
        }

        var fence: ArrayList<ArrayList<String>> = new ArrayList<ArrayList<String>>()
        var i: Int64 = 0
        while i < rails {
            var row: ArrayList<String> = new ArrayList<String>()
            var j: Int64 = 0
            while j < n {
                row.add("\n")
                j = j + 1
            }
            fence.add(row)
            i = i + 1
        }

        var direction: Int64 = -1
        var rowIdx: Int64 = 0
        var colIdx: Int64 = 0

        var k: Int64 = 0
        while k < n {
            if rowIdx == 0 || rowIdx == (rails - 1) {
                direction = -direction
            }
            fence.get(rowIdx).set(colIdx, "*")
            colIdx = colIdx + 1
            rowIdx = rowIdx + direction
            k = k + 1
        }

        var index: Int64 = 0
        i = 0
        while i < rails {
            var j2: Int64 = 0
            while j2 < n {
                if fence.get(i).get(j2) == "*" {
                    let ch: String = encrypted_text.substring(index, index + 1)
                    fence.get(i).set(j2, ch)
                    index = index + 1
                }
                j2 = j2 + 1
            }
            i = i + 1
        }

        var plain_text: String = ""
        direction = -1
        rowIdx = 0
        colIdx = 0
        k = 0
        while k < n {
            if rowIdx == 0 || rowIdx == (rails - 1) {
                direction = -direction
            }
            plain_text = plain_text + fence.get(rowIdx).get(colIdx)
            colIdx = colIdx + 1
            rowIdx = rowIdx + direction
            k = k + 1
        }

        return plain_text
    }

    private func alphabetLower(): String {
        return "abcdefghijklmnopqrstuvwxyz"
    }

    private func alphabetUpper(): String {
        return "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    }

    private func indexInAlphabet(alphabet: String, ch: String): Int64 {
        var i: Int64 = 0
        let n: Int64 = alphabet.length()
        while i < n {
            if alphabet.substring(i, i + 1) == ch {
                return i
            }
            i = i + 1
        }
        return -1
    }

    private func toLowerChar(ch: String): String {
        let upper: String = this.alphabetUpper()
        let lower: String = this.alphabetLower()
        let idx: Int64 = this.indexInAlphabet(upper, ch)
        if idx != -1 {
            return lower.substring(idx, idx + 1)
        }
        return ch
    }

    private func toUpperChar(ch: String): String {
        let upper: String = this.alphabetUpper()
        let lower: String = this.alphabetLower()
        let idx: Int64 = this.indexInAlphabet(lower, ch)
        if idx != -1 {
            return upper.substring(idx, idx + 1)
        }
        return ch
    }
}

